affine_plane_ag2.body:
{
    if p < 2 || p > 13 {
        return Err(FiniteGeometryError::InvalidDimension);
    }
    for d in 2..p {
        if p % d == 0 {
            return Err(FiniteGeometryError::NotPrime(p));
        }
    }
    let num_points = p * p;
    let mut lines = Vec::with_capacity(p * (p + 1));

    for c in 0..p {
        let mut line = Vec::with_capacity(p);
        for y in 0..p {
            line.push(c * p + y);
        }
        lines.push(line);
    }

    for m in 0..p {
        for c in 0..p {
            let mut line = Vec::with_capacity(p);
            for x in 0..p {
                let y = (m * x + c) % p;
                line.push(x * p + y);
            }
            lines.push(line);
        }
    }

    IncidenceStructure::new(num_points, lines)
}

