admit_product.signature:
fn admit_product(
    operation: &'static str,
    left: usize,
    right: usize,
    maximum: usize,
) -> Result<usize, FiniteGeometryError>

admit_product.body:
{
    let requested = left
        .checked_mul(right)
        .ok_or(FiniteGeometryError::ResourceLimit {
            operation,
            requested: usize::MAX,
            maximum,
        })?;
    if requested > maximum {
        return Err(FiniteGeometryError::ResourceLimit {
            operation,
            requested,
            maximum,
        });
    }
    Ok(requested)
}

admit_incidence_entries.body:
{
    let mut entries = 0usize;
    for line in lines {
        entries = entries
            .checked_add(line.len())
            .ok_or(FiniteGeometryError::ResourceLimit {
                operation: "incidence entries",
                requested: usize::MAX,
                maximum: MAX_GEOMETRY_CELLS,
            })?;
        if entries > MAX_GEOMETRY_CELLS {
            return Err(FiniteGeometryError::ResourceLimit {
                operation: "incidence entries",
                requested: entries,
                maximum: MAX_GEOMETRY_CELLS,
            });
        }
    }
    Ok(())
}

admit_ray_shape.body:
{
    let n = vectors.len();
    admit_product("ray matrix cells", n, n, MAX_GEOMETRY_CELLS)?;
    let width = vectors.first().map_or(0, Vec::len);
    for (index, vector) in vectors.iter().enumerate() {
        if vector.len() != width {
            return Err(FiniteGeometryError::DimensionMismatch {
                index,
                expected: width,
                found: vector.len(),
            });
        }
    }
    admit_product("ray input cells", n, width, MAX_GEOMETRY_CELLS)?;
    let pairs = if n == 0 { 0 } else { n * (n - 1) / 2 };
    admit_product("ray dot terms", pairs, width, MAX_GEOMETRY_WORK)?;
    Ok(())
}

mark_orthogonal_row.signature:
fn mark_orthogonal_row(
    adj: &mut [Vec<bool>],
    vectors: &[Vec<i64>],
    i: usize,
) -> Result<(), FiniteGeometryError>

mark_orthogonal_row.body:
{
    let left = match vectors.get(i) {
        Some(row) => row,
        None => {
            return Err(FiniteGeometryError::PointOutOfBounds {
                point: i,
                num_points: vectors.len(),
            })
        }
    };
    for j in (i + 1)..vectors.len() {
        mark_pair(adj, vectors, left, i, j)?;
    }
    Ok(())
}

mark_pair.body:
{
    let right = match vectors.get(j) {
        Some(row) => row,
        None => {
            return Err(FiniteGeometryError::PointOutOfBounds {
                point: j,
                num_points: vectors.len(),
            })
        }
    };
    let product = match dot(left, right) {
        Ok(value) => value,
        Err(err) => return Err(err),
    };
    if product == 0 {
        return set_symmetric(adj, i, j);
    }
    Ok(())
}

dot.body:
{
    if left.len() != right.len() {
        return Err(FiniteGeometryError::DimensionMismatch {
            index: 1,
            expected: left.len(),
            found: right.len(),
        });
    }
    let mut acc = 0i64;
    for (a, b) in left.iter().zip(right) {
        let prod = a.checked_mul(*b).ok_or(FiniteGeometryError::DotOverflow {
            left: *a,
            right: *b,
        })?;
        acc = acc
            .checked_add(prod)
            .ok_or(FiniteGeometryError::DotOverflow {
                left: acc,
                right: prod,
            })?;
    }
    Ok(acc)
}

set_symmetric.body:
{
    write_cell(adj, i, j)?;
    write_cell(adj, j, i)
}

write_cell.body:
{
    let rows = adj.len();
    let line = adj
        .get_mut(row)
        .ok_or(FiniteGeometryError::PointOutOfBounds {
            point: row,
            num_points: rows,
        })?;
    let cols = line.len();
    let cell = line
        .get_mut(col)
        .ok_or(FiniteGeometryError::PointOutOfBounds {
            point: col,
            num_points: cols,
        })?;
    *cell = true;
    Ok(())
}
